MAX_BYTES = 1048576


def main():
    data = base64.b64decode(IMAGE_B64)
    if len(data) > MAX_BYTES:
        raise ValueError(f"image too large: {len(data)} bytes")
    os.makedirs("/output", exist_ok=True)
    with open("/output/entry.png", "wb") as f:
        f.write(data)

    # Verify the written file round-trips byte-identical to the embedded image.
    with open("/output/entry.png", "rb") as f:
        written = f.read()
    if written != data:
        raise ValueError("entry.png does not match the embedded image")


if __name__ == "__main__":
    main()
